1	import { create } from 'zustand';
2	import { persist } from 'zustand/middleware';
3	import { playTick, playTimerStart, playTimerPause, playHatchFanfare, playTimerAlarm, playMarkBell } from '../core/audioFx';
4	import { isMarkHit, parseMarkInput, MAX_CUSTOM_MARKS, MIN_CHUNK_SECONDS } from '../core/timerMarks';
5	import { persistArcProgress, fetchArcProgress, resetArcProgress } from '../../../core/syncEngine';
6	import {
7	  rollWeightedDino,
8	  calculatePomodoroTime,
9	  advanceDinoOneEvo,
10	  getDinoRollChance,
11	  type PomodoroTimeResult,
12	} from '../core/dinoMath';
13	
14	export interface UserProgressData {
15	  owned_dinos: Record<string, { number: number; rank: number; ferocity?: number }>;
16	}
17	
18	interface DinoPomodoroState {
19	  // Current Rolled Dino for Pomodoro
20	  currentDino: any | null;
21	  chancePercent: number;
22	  categoryChancePercent: number;
23	  categoryLabel: string;
24	  categoryCount: number;
25	  timeCalc: PomodoroTimeResult | null;
26	
27	  // Active Timer
28	  sessionDuration: number; // in seconds
29	  timeRemaining: number; // in seconds
30	  isRunning: boolean;
31	
32	  // Timer Marks: bell rings when elapsed time hits a mark; countdown keeps running
33	  marks: number[]; // custom checkpoints, in elapsed seconds (sorted)
34	  chunkSeconds: number; // repeating chunk size in seconds (0 = off)
35	
36	  // Audio Config
37	  soundEnabled: boolean;
38	  tickSoundEnabled: boolean;
39	
40	  // User Progress (Dinos Owned)
41	  userProgress: UserProgressData;
42	
43	  // Last Claimed Dino for Instant Celebration / Feedback
44	  lastClaimedDino: any | null;
45	
46	  // Actions
47	  initializeOrRollDino: (dinoLibrary: any[]) => void;
48	  swapDino: (dinoLibrary: any[]) => void;
49	  toggleTimer: () => void;
50	  startTimer: () => void;
51	  pauseTimer: () => void;
52	  claimDino: (dinoLibrary: any[]) => void;
53	  resetAllDinos: (dinoLibrary: any[]) => Promise<void>;
54	  tick: () => void;
55	  toggleSound: () => void;
56	  toggleTickSound: () => void;
57	  addMark: (input: string) => boolean;
58	  removeMark: (seconds: number) => void;
59	  clearMarks: () => void;
60	  setChunk: (input: string) => boolean;
61	  dismissCelebration: () => void;
62	  clearChunk: () => void;
63	  syncWithBackend: () => Promise<void>;
64	}
65	
66	export const useDinoPomodoroStore = create<DinoPomodoroState>()(
67	  persist(
68	    (set, get) => ({
69	      currentDino: null,
70	      chancePercent: 0,
71	      categoryChancePercent: 0,
72	      categoryLabel: '',
73	      categoryCount: 0,
74	      timeCalc: null,
75	
76	      sessionDuration: 25 * 60,
77	      timeRemaining: 25 * 60,
78	      isRunning: false,
79	
80	      marks: [],
81	      chunkSeconds: 0,
82	
83	      soundEnabled: true,
84	      tickSoundEnabled: false,
85	
86	      userProgress: { owned_dinos: {} },
87	      lastClaimedDino: null,
88	
89	      initializeOrRollDino: (dinoLibrary) => {
90	        if (!dinoLibrary || dinoLibrary.length === 0) return;
91	        const { currentDino, userProgress } = get();
92	
93	        // If a dino is already rolled, recompute its time calculation and pool chance with current userProgress
94	        if (currentDino) {
95	          const uuid = currentDino.uuid || currentDino.id || currentDino.name;
96	          const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
97	          const calc = calculatePomodoroTime(currentDino, userCount, userProgress);
98	          const rollData = getDinoRollChance(currentDino, dinoLibrary, userProgress);
99	          const prev = get();
100	          const elapsed = Math.max(0, prev.sessionDuration - prev.timeRemaining);
101	          set({
102	            chancePercent: rollData.chancePercent,
103	            categoryChancePercent: rollData.categoryChancePercent,
104	            categoryLabel: rollData.categoryLabel,
105	            categoryCount: rollData.categoryCount,
106	            timeCalc: calc,
107	            sessionDuration: calc.durationSeconds,
108	            // Completed stays completed; otherwise keep elapsed time under the (possibly new) duration
109	            timeRemaining:
110	              prev.timeRemaining <= 0
111	                ? 0
112	                : Math.max(1, calc.durationSeconds - Math.min(elapsed, calc.durationSeconds - 1)),
113	          });
114	          return;
115	        }
116	
117	        // Roll new dino with userProgress affinity
118	        const rolled = rollWeightedDino(dinoLibrary, userProgress);
119	        const uuid = rolled.dino.uuid || rolled.dino.id || rolled.dino.name;
120	        const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
121	        const calc = calculatePomodoroTime(rolled.dino, userCount, userProgress);
122	
123	        set({
124	          currentDino: rolled.dino,
125	          chancePercent: rolled.chancePercent,
126	          categoryChancePercent: rolled.categoryChancePercent,
127	          categoryLabel: rolled.categoryLabel,
128	          categoryCount: rolled.categoryCount,
129	          timeCalc: calc,
130	          sessionDuration: calc.durationSeconds,
131	          timeRemaining: calc.durationSeconds,
132	          isRunning: false,
133	        });
134	      },
135	
136	      swapDino: (dinoLibrary) => {
137	        if (!dinoLibrary || dinoLibrary.length === 0) return;
138	        const { userProgress, soundEnabled } = get();
139	
140	        if (soundEnabled) {
141	          playTimerPause();
142	        }
143	
144	        // Roll a brand new weighted dino from all dinos with userProgress affinity
145	        const rolled = rollWeightedDino(dinoLibrary, userProgress);
146	        const uuid = rolled.dino.uuid || rolled.dino.id || rolled.dino.name;
147	        const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
148	        const calc = calculatePomodoroTime(rolled.dino, userCount, userProgress);
149	
150	        set({
151	          currentDino: rolled.dino,
152	          chancePercent: rolled.chancePercent,
153	          categoryChancePercent: rolled.categoryChancePercent,
154	          categoryLabel: rolled.categoryLabel,
155	          categoryCount: rolled.categoryCount,
156	          timeCalc: calc,
157	          sessionDuration: calc.durationSeconds,
158	          timeRemaining: calc.durationSeconds,
159	          isRunning: false,
160	        });
161	      },
162	
163	      toggleTimer: () => {
164	        const { isRunning, timeRemaining, soundEnabled } = get();
165	        // If timer reached zero, clicking does not restart — must claim or swap
166	        if (timeRemaining <= 0) return;
167	
168	        // Proactively request browser notification permission on user interaction
169	        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'default') {
170	          Notification.requestPermission().catch(() => {});
171	        }
172	
173	        if (isRunning) {
174	          if (soundEnabled) playTimerPause();
175	          set({ isRunning: false });
176	        } else {
177	          if (soundEnabled) playTimerStart();
178	          set({ isRunning: true });
179	        }
180	      },
181	
182	      startTimer: () => {
183	        const { timeRemaining, soundEnabled } = get();
184	        if (timeRemaining <= 0) return;
185	
186	        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'default') {
187	          Notification.requestPermission().catch(() => {});
188	        }
189	
190	        if (soundEnabled) playTimerStart();
191	        set({ isRunning: true });
192	      },
193	
194	      pauseTimer: () => {
195	        const { soundEnabled } = get();
196	        if (soundEnabled) playTimerPause();
197	        set({ isRunning: false });
198	      },
199	
200	      claimDino: (dinoLibrary) => {
201	        const { currentDino, userProgress, timeRemaining, soundEnabled } = get();
202	        if (!currentDino || timeRemaining > 0) return;
203	
204	        const uuid = currentDino.uuid || currentDino.id || currentDino.name;
205	        const currentCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
206	        const evoCount = currentDino.evolutions?.length || 4;
207	
208	        // Advance 1 evo at a time
209	        const newCount = advanceDinoOneEvo(currentCount, evoCount);
210	        const newRank = Math.min(
211	          evoCount,
212	          currentCount === 0 ? 1 : (userProgress.owned_dinos[uuid]?.rank || 1) + 1
213	        );
214	        const evoFero =
215	          currentDino.evolutions?.[newRank - 1]?.ferocity || currentDino.max_ferocity || 350;
216	
217	        const updatedOwned = {
218	          ...userProgress.owned_dinos,
219	          [uuid]: {
220	            number: newCount,
221	            rank: newRank,
222	            ferocity: evoFero,
223	          },
224	        };
225	
226	        const updatedProgress = { owned_dinos: updatedOwned };
227	
228	        // 1. Fanfare
229	        if (soundEnabled) {
230	          playHatchFanfare();
231	        }
232	
233	        // 2. Persist to SQLite Backend
234	        try {
