import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { playTick, playTimerStart, playTimerPause, playHatchFanfare, playTimerAlarm, playMarkBell } from '../core/audioFx';
import { isMarkHit, parseMarkInput, MAX_CUSTOM_MARKS, MIN_CHUNK_SECONDS } from '../core/timerMarks';
import { persistArcProgress, fetchArcProgress, resetArcProgress } from '../../../core/syncEngine';
import {
  rollWeightedDino,
  calculatePomodoroTime,
  advanceDinoOneEvo,
  getDinoRollChance,
  type PomodoroTimeResult,
} from '../core/dinoMath';

export interface UserProgressData {
  owned_dinos: Record<string, { number: number; rank: number; ferocity?: number }>;
}

interface DinoPomodoroState {
  // Current Rolled Dino for Pomodoro
  currentDino: any | null;
  chancePercent: number;
  categoryChancePercent: number;
  categoryLabel: string;
  categoryCount: number;
  timeCalc: PomodoroTimeResult | null;

  // Active Timer
  sessionDuration: number; // in seconds
  timeRemaining: number; // in seconds
  isRunning: boolean;

  // Timer Marks: bell rings when elapsed time hits a mark; countdown keeps running
  marks: number[]; // custom checkpoints, in elapsed seconds (sorted)
  chunkSeconds: number; // repeating chunk size in seconds (0 = off)

  // Audio Config
  soundEnabled: boolean;
  tickSoundEnabled: boolean;

  // User Progress (Dinos Owned)
  userProgress: UserProgressData;

  // Last Claimed Dino for Instant Celebration / Feedback
  lastClaimedDino: any | null;

  // Actions
  initializeOrRollDino: (dinoLibrary: any[]) => void;
  swapDino: (dinoLibrary: any[]) => void;
  toggleTimer: () => void;
  startTimer: () => void;
  pauseTimer: () => void;
  claimDino: (dinoLibrary: any[]) => void;
  resetAllDinos: (dinoLibrary: any[]) => Promise<void>;
  tick: () => void;
  toggleSound: () => void;
  toggleTickSound: () => void;
  addMark: (input: string) => boolean;
  removeMark: (seconds: number) => void;
  clearMarks: () => void;
  setChunk: (input: string) => boolean;
  dismissCelebration: () => void;
  clearChunk: () => void;
  syncWithBackend: () => Promise<void>;
}

export const useDinoPomodoroStore = create<DinoPomodoroState>()(
  persist(
    (set, get) => ({
      currentDino: null,
      chancePercent: 0,
      categoryChancePercent: 0,
      categoryLabel: '',
      categoryCount: 0,
      timeCalc: null,

      sessionDuration: 25 * 60,
      timeRemaining: 25 * 60,
      isRunning: false,

      marks: [],
      chunkSeconds: 0,

      soundEnabled: true,
      tickSoundEnabled: false,

      userProgress: { owned_dinos: {} },
      lastClaimedDino: null,

      initializeOrRollDino: (dinoLibrary) => {
        if (!dinoLibrary || dinoLibrary.length === 0) return;
        const { currentDino, userProgress } = get();

        // If a dino is already rolled, recompute its time calculation and pool chance with current userProgress
        if (currentDino) {
          const uuid = currentDino.uuid || currentDino.id || currentDino.name;
          const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
          const calc = calculatePomodoroTime(currentDino, userCount, userProgress);
          const rollData = getDinoRollChance(currentDino, dinoLibrary, userProgress);
          const prev = get();
          const elapsed = Math.max(0, prev.sessionDuration - prev.timeRemaining);
          set({
            chancePercent: rollData.chancePercent,
            categoryChancePercent: rollData.categoryChancePercent,
            categoryLabel: rollData.categoryLabel,
            categoryCount: rollData.categoryCount,
            timeCalc: calc,
            sessionDuration: calc.durationSeconds,
            // Completed stays completed; otherwise keep elapsed time under the (possibly new) duration
            timeRemaining:
              prev.timeRemaining <= 0
                ? 0
                : Math.max(1, calc.durationSeconds - Math.min(elapsed, calc.durationSeconds - 1)),
          });
          return;
        }

        // Roll new dino with userProgress affinity
        const rolled = rollWeightedDino(dinoLibrary, userProgress);
        const uuid = rolled.dino.uuid || rolled.dino.id || rolled.dino.name;
        const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
        const calc = calculatePomodoroTime(rolled.dino, userCount, userProgress);

        set({
          currentDino: rolled.dino,
          chancePercent: rolled.chancePercent,
          categoryChancePercent: rolled.categoryChancePercent,
          categoryLabel: rolled.categoryLabel,
          categoryCount: rolled.categoryCount,
          timeCalc: calc,
          sessionDuration: calc.durationSeconds,
          timeRemaining: calc.durationSeconds,
          isRunning: false,
        });
      },

      swapDino: (dinoLibrary) => {
        if (!dinoLibrary || dinoLibrary.length === 0) return;
        const { userProgress, soundEnabled } = get();

        if (soundEnabled) {
          playTimerPause();
        }

        // Roll a brand new weighted dino from all dinos with userProgress affinity
        const rolled = rollWeightedDino(dinoLibrary, userProgress);
        const uuid = rolled.dino.uuid || rolled.dino.id || rolled.dino.name;
        const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
        const calc = calculatePomodoroTime(rolled.dino, userCount, userProgress);

        set({
          currentDino: rolled.dino,
          chancePercent: rolled.chancePercent,
          categoryChancePercent: rolled.categoryChancePercent,
          categoryLabel: rolled.categoryLabel,
          categoryCount: rolled.categoryCount,
          timeCalc: calc,
          sessionDuration: calc.durationSeconds,
          timeRemaining: calc.durationSeconds,
          isRunning: false,
        });
      },

      toggleTimer: () => {
        const { isRunning, timeRemaining, soundEnabled } = get();
        // If timer reached zero, clicking does not restart — must claim or swap
        if (timeRemaining <= 0) return;

        // Proactively request browser notification permission on user interaction
        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'default') {
          Notification.requestPermission().catch(() => {});
        }

        if (isRunning) {
          if (soundEnabled) playTimerPause();
          set({ isRunning: false });
        } else {
          if (soundEnabled) playTimerStart();
          set({ isRunning: true });
        }
      },

      startTimer: () => {
        const { timeRemaining, soundEnabled } = get();
        if (timeRemaining <= 0) return;

        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'default') {
          Notification.requestPermission().catch(() => {});
        }

        if (soundEnabled) playTimerStart();
        set({ isRunning: true });
      },

      pauseTimer: () => {
        const { soundEnabled } = get();
        if (soundEnabled) playTimerPause();
        set({ isRunning: false });
      },

      claimDino: (dinoLibrary) => {
        const { currentDino, userProgress, timeRemaining, soundEnabled } = get();
        if (!currentDino || timeRemaining > 0) return;

        const uuid = currentDino.uuid || currentDino.id || currentDino.name;
        const currentCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
        const evoCount = currentDino.evolutions?.length || 4;

        // Advance 1 evo at a time
        const newCount = advanceDinoOneEvo(currentCount, evoCount);
        const newRank = Math.min(
          evoCount,
          currentCount === 0 ? 1 : (userProgress.owned_dinos[uuid]?.rank || 1) + 1
        );
        const evoFero =
          currentDino.evolutions?.[newRank - 1]?.ferocity || currentDino.max_ferocity || 350;

        const updatedOwned = {
          ...userProgress.owned_dinos,
          [uuid]: {
            number: newCount,
            rank: newRank,
            ferocity: evoFero,
          },
        };

        const updatedProgress = { owned_dinos: updatedOwned };

        // 1. Fanfare
        if (soundEnabled) {
          playHatchFanfare();
        }

        // 2. Persist to SQLite Backend
        try {
          persistArcProgress(updatedProgress as any).catch(() => {});
        } catch {
          // Ignore
        }

        // 3. Roll a new random dino for the next session
        let nextDinoObj = null;
        let nextChance = 0;
        let nextCatChance = 0;
        let nextCatLabel = '';
        let nextCatCount = 0;
        let nextCalc = null;

        if (dinoLibrary && dinoLibrary.length > 0) {
          const rolled = rollWeightedDino(dinoLibrary, updatedProgress);
          nextDinoObj = rolled.dino;
          nextChance = rolled.chancePercent;
          nextCatChance = rolled.categoryChancePercent;
          nextCatLabel = rolled.categoryLabel;
          nextCatCount = rolled.categoryCount;
          const nextKey = nextDinoObj.uuid || nextDinoObj.id || nextDinoObj.name;
          const nextCount = Number((updatedOwned as Record<string, any>)[nextKey]?.number || 0);
          nextCalc = calculatePomodoroTime(nextDinoObj, nextCount, updatedProgress);
        }

        set({
          userProgress: updatedProgress,
          lastClaimedDino: {
            dino: currentDino,
            rank: newRank,
            count: newCount,
          },
          currentDino: nextDinoObj || currentDino,
          chancePercent: nextChance,
          categoryChancePercent: nextCatChance,
          categoryLabel: nextCatLabel,
          categoryCount: nextCatCount,
          timeCalc: nextCalc,
          sessionDuration: nextCalc ? nextCalc.durationSeconds : 25 * 60,
          timeRemaining: nextCalc ? nextCalc.durationSeconds : 25 * 60,
          isRunning: false,
        });

        // Browser notification if granted
        if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
          try {
            new Notification('Dino Claimed! 🦖', {
              body: `${currentDino.name} has been upgraded to EVO ${newRank}! A new dinosaur has been rolled!`,
              icon: currentDino.image_url,
            });
          } catch {
            // Ignore
          }
        }
      },

      resetAllDinos: async (dinoLibrary) => {
        // Reset local progress
        const emptyProgress = { owned_dinos: {} };

        // Reset SQLite backend
        try {
          await resetArcProgress();
        } catch (e) {
          console.warn('[DinoPomodoroStore] Error clearing backend progress:', e);
        }

        // Roll fresh dino
        let freshDino = null;
        let freshChance = 0;
        let freshCatChance = 0;
        let freshCatLabel = '';
        let freshCatCount = 0;
        let freshCalc = null;

        if (dinoLibrary && dinoLibrary.length > 0) {
          const rolled = rollWeightedDino(dinoLibrary, emptyProgress);
          freshDino = rolled.dino;
          freshChance = rolled.chancePercent;
          freshCatChance = rolled.categoryChancePercent;
          freshCatLabel = rolled.categoryLabel;
          freshCatCount = rolled.categoryCount;
          freshCalc = calculatePomodoroTime(freshDino, 0, emptyProgress);
        }

        set({
          userProgress: emptyProgress,
          lastClaimedDino: null,
          currentDino: freshDino,
          chancePercent: freshChance,
          categoryChancePercent: freshCatChance,
          categoryLabel: freshCatLabel,
          categoryCount: freshCatCount,
          timeCalc: freshCalc,
          sessionDuration: freshCalc ? freshCalc.durationSeconds : 25 * 60,
          timeRemaining: freshCalc ? freshCalc.durationSeconds : 25 * 60,
          isRunning: false,
        });
      },

      tick: () => {
        const { isRunning, timeRemaining, tickSoundEnabled, soundEnabled } = get();
        if (!isRunning) return;

        if (timeRemaining > 1) {
          const { sessionDuration, marks, chunkSeconds } = get();
          const elapsedAfterTick = sessionDuration - (timeRemaining - 1);

          // Mark reached: ring the bell, but the countdown keeps going to the real end
          if (soundEnabled && isMarkHit(elapsedAfterTick, marks, chunkSeconds, sessionDuration)) {
            playMarkBell();
          } else if (tickSoundEnabled && soundEnabled) {
            playTick();
          }
          set({ timeRemaining: timeRemaining - 1 });
        } else if (timeRemaining === 1) {
          // Reached zero! Stop and play generic digital timer alarm
          if (soundEnabled) {
            playTimerAlarm();
          }

          // Desktop OS push notification when incubation finishes
          if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
            try {
              const dino = get().currentDino;
              new Notification('🦖 Incubation Complete!', {
                body: `${dino?.name || 'Prehistoric Specimen'} is ready for ascension! Click to claim.`,
                icon: dino?.image_url,
              });
            } catch {
              // Ignore
            }
          }

          set({
            timeRemaining: 0,
            isRunning: false,
          });
        }
      },

      toggleSound: () => {
        set((state) => ({ soundEnabled: !state.soundEnabled }));
      },

      toggleTickSound: () => {
        set((state) => ({ tickSoundEnabled: !state.tickSoundEnabled }));
      },

      addMark: (input) => {
        const seconds = parseMarkInput(input);
        if (seconds === null) return false;
        const { marks, sessionDuration } = get();
        // A mark at/after the end is meaningless — the final alarm covers it
        if (seconds >= sessionDuration) return false;
        if (marks.includes(seconds)) return true;
        if (marks.length >= MAX_CUSTOM_MARKS) return false;
        set({ marks: [...marks, seconds].sort((a, b) => a - b) });
        return true;
      },

      removeMark: (seconds) => {
        set((state) => ({ marks: state.marks.filter((m) => m !== seconds) }));
      },

      clearMarks: () => {
        set({ marks: [] });
      },

      setChunk: (input) => {
        const seconds = parseMarkInput(input);
        if (seconds === null || seconds < MIN_CHUNK_SECONDS) return false;
        set({ chunkSeconds: seconds });
        return true;
      },

      clearChunk: () => {
        set({ chunkSeconds: 0 });
      },

      dismissCelebration: () => {
        set({ lastClaimedDino: null });
      },

      syncWithBackend: async () => {
        try {
          const backend = await fetchArcProgress();
          if (backend?.owned_dinos) {
            set((state) => ({
              userProgress: {
                owned_dinos: {
                  ...state.userProgress.owned_dinos,
                  ...backend.owned_dinos,
                },
              },
            }));
          }
        } catch {
          // Ignore
        }
      },
    }),
    {
      name: 'dino_pomodoro_storage_v2',
      partialize: (state) => ({
        userProgress: state.userProgress,
        currentDino: state.currentDino,
        chancePercent: state.chancePercent,
        categoryChancePercent: state.categoryChancePercent,
        categoryLabel: state.categoryLabel,
        categoryCount: state.categoryCount,
        timeCalc: state.timeCalc,
        sessionDuration: state.sessionDuration,
        timeRemaining: state.timeRemaining,
        soundEnabled: state.soundEnabled,
        tickSoundEnabled: state.tickSoundEnabled,
        marks: state.marks,
        chunkSeconds: state.chunkSeconds,
      }),
    }
  )
);

import React, { useMemo } from 'react';
import {
  Shuffle,
  Flame,
  Dna,
  Volume2,
  VolumeX,
  Trophy,
  Shield,
  Swords,
  Sparkles,
  Quote,
  BookOpen,
} from 'lucide-react';
import { useDinoPomodoroStore } from '../../../store/useDinoPomodoroStore';
import { rutGonTime } from '../../../../arc-jurassic/core/rutGonTime';
import { DinoCard } from '../../molecule/DinoCard';
import { EvoAvatar } from '../../../../arc-jurassic/components/molecule/EvoAvatar/EvoAvatar';
import { calcDinoRank, getDinoAvatarUrl } from '../../../../arc-jurassic/core/evolutionEngine';
import lookupRawData from '../../../../arc-jurassic/data/lookup.json';
import {
  formatCategoryLabel,
  getDinoCategoryKey,
  getDinoRollChance,
  FEROCITY_MINUTES_DIVISOR,
  ferocityToSeconds,
} from '../../../core/dinoMath';
import { computeEffectiveMarks } from '../../../core/timerMarks';
import { MarksPanel } from './MarksPanel';

interface PomodoroTabProps {
  dinoLibrary: any[];
}

export const PomodoroTab: React.FC<PomodoroTabProps> = ({ dinoLibrary }) => {
  const {
    currentDino,
    chancePercent,
    categoryChancePercent,
    categoryLabel,
    categoryCount,
    timeCalc,
    sessionDuration,
    timeRemaining,
    isRunning,
    soundEnabled,
    tickSoundEnabled,
    marks,
    chunkSeconds,
    userProgress,
    toggleTimer,
    swapDino,
    claimDino,
    toggleSound,
    toggleTickSound,
  } = useDinoPomodoroStore();

  // Dynamically compute active roll probabilities with calibrated inverse formula (unconditional hook)
  const activeRollData = useMemo(() => {
    if (!currentDino || !dinoLibrary || dinoLibrary.length === 0) return null;
    return getDinoRollChance(currentDino, dinoLibrary, userProgress);
  }, [currentDino, dinoLibrary, userProgress]);

  if (!currentDino) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-center p-8">
        <div className="text-4xl animate-bounce mb-3">🥚</div>
        <p className="font-cinzel text-lg text-amber-300">Rolling prehistoric specimen...</p>
      </div>
    );
  }

  const uuid = currentDino.uuid || currentDino.id || currentDino.name;
  const ownedData = userProgress.owned_dinos[uuid];
  const currentCount = Number(ownedData?.number || 0);
  const isOwned = currentCount > 0;

  const activeChancePercent = activeRollData?.chancePercent ?? chancePercent;
  const activeCategoryChancePercent = activeRollData?.categoryChancePercent ?? categoryChancePercent;
  const activeCategoryLabel =
    activeRollData?.categoryLabel ||
    categoryLabel ||
    formatCategoryLabel(getDinoCategoryKey(currentDino));
  const activeCategoryCount = activeRollData?.categoryCount ?? categoryCount ?? 0;

  const evolutions = Array.isArray(currentDino.evolutions) && currentDino.evolutions.length > 0
    ? currentDino.evolutions
    : [
        { level: 10, ferocity: currentDino.evo1_ferocity || 300, health: 350, damage: 200 },
        { level: 20, ferocity: Math.round((currentDino.evo1_ferocity || 300) * 1.7), health: 600, damage: 350 },
        { level: 30, ferocity: Math.round((currentDino.evo1_ferocity || 300) * 2.6), health: 900, damage: 520 },
        { level: 40, ferocity: currentDino.max_ferocity || Math.round((currentDino.evo1_ferocity || 300) * 3.7), health: 1300, damage: 750 },
      ];
  const currentRank = calcDinoRank(currentCount, evolutions.length);
  const nextRank = timeCalc?.nextRank || 1;
  const nextEvoFerocity = timeCalc?.nextEvoFerocity || 300;
  const partnerCount = timeCalc?.partnerCount || 0;

  const targetFactIndex = Math.max(0, Math.min(3, nextRank - 1));
  const targetEvoFact =
    currentDino.facts?.[targetFactIndex] ||
    currentDino.facts?.[0] ||
    'Prehistoric specimen awaiting genetic incubation and biometric awakening.';

  const rawRarity = (currentDino.rarity || 'common').toLowerCase();
  const frameUrl =
    (lookupRawData.portrait_frames as Record<string, string>)[rawRarity] ||
    `https://cdn.paleo.gg/games/jwtg/images/portrait-frame/${rawRarity}.png`;

  // Circular progress calculation
  const progressPercent = sessionDuration > 0
    ? Math.min(100, Math.max(0, ((sessionDuration - timeRemaining) / sessionDuration) * 100))
    : 100;

  const isComplete = timeRemaining <= 0;

  // Bell marks inside this session (custom + repeating chunk)
  const effectiveMarks = computeEffectiveMarks(marks, chunkSeconds, sessionDuration);

  // Sensitive Click Handler: Clicking anywhere on the main card/pod toggles Start/Stop
  const handleHitboxClick = (e: React.MouseEvent) => {
    // If user clicked directly on an interactive button or quote block, let it handle it
    const target = e.target as HTMLElement;
    if (target.closest('button') || target.closest('blockquote')) {
      return;
    }
    toggleTimer();
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-4 space-y-6">
      {/* ── TOP TELEMETRY STRIP ── */}
      <div className="bg-[#120d1c]/90 backdrop-blur-md border border-[#2e233d] rounded-2xl px-5 py-3 flex flex-wrap items-center justify-between gap-3 shadow-lg">
        <div className="flex items-center gap-2.5 flex-wrap">
          {/* Individual Dino Chance telemetry */}
