            >
              <Sparkles className="w-3.5 h-3.5 text-emerald-400" />
              <span>+{Math.round(partnerCount * 10)}% AFFINITY BOOST</span>
              <span className="text-[10px] text-emerald-400/80 font-sans">({partnerCount} related dinos)</span>
            </div>
