          {/* Formula breakdown */}
          <div className="flex items-center gap-1.5 bg-[#140e20] px-3 py-1 rounded-xl border border-[#3b2a52] text-xs font-mono text-sky-300">
            <Flame className="w-3.5 h-3.5 text-amber-400" />
            <span>
