                  {currentDino.name}
                </h2>
                <div className="text-xs font-cinzel text-[#8c7a9e] tracking-wider uppercase mt-0.5">
                  Target: {isOwned ? `EVO ${nextRank} ASCENSION` : 'DISCOVERY & UNLOCK'}
