358	
359	        if (timeRemaining > 1) {
360	          const { sessionDuration, marks, chunkSeconds } = get();
361	          const elapsedAfterTick = sessionDuration - (timeRemaining - 1);
362	
363	          // Mark reached: ring the bell, but the countdown keeps going to the real end
364	          if (soundEnabled && isMarkHit(elapsedAfterTick, marks, chunkSeconds, sessionDuration)) {
365	            playMarkBell();
366	          } else if (tickSoundEnabled && soundEnabled) {
367	            playTick();
368	          }
369	          set({ timeRemaining: timeRemaining - 1 });
370	        } else if (timeRemaining === 1) {
371	          // Reached zero! Stop and play generic digital timer alarm
372	          if (soundEnabled) {
373	            playTimerAlarm();
374	          }
375	
376	          // Desktop OS push notification when incubation finishes
377	          if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
378	            try {
379	              const dino = get().currentDino;
380	              new Notification('🦖 Incubation Complete!', {
381	                body: `${dino?.name || 'Prehistoric Specimen'} is ready for ascension! Click to claim.`,
382	                icon: dino?.image_url,
383	              });
384	            } catch {
385	              // Ignore
386	            }
387	          }
388	
389	          set({
390	            timeRemaining: 0,
391	            isRunning: false,
392	          });
393	        }
394	      },
395	
396	      toggleSound: () => {
397	        set((state) => ({ soundEnabled: !state.soundEnabled }));
398	      },
399	
400	      toggleTickSound: () => {
401	        set((state) => ({ tickSoundEnabled: !state.tickSoundEnabled }));
402	      },
403	
404	      addMark: (input) => {
405	        const seconds = parseMarkInput(input);
406	        if (seconds === null) return false;
407	        const { marks, sessionDuration } = get();
408	        // A mark at/after the end is meaningless — the final alarm covers it
409	        if (seconds >= sessionDuration) return false;
410	        if (marks.includes(seconds)) return true;
411	        if (marks.length >= MAX_CUSTOM_MARKS) return false;
412	        set({ marks: [...marks, seconds].sort((a, b) => a - b) });
413	        return true;
414	      },
415	
416	      removeMark: (seconds) => {
417	        set((state) => ({ marks: state.marks.filter((m) => m !== seconds) }));
418	      },
419	
420	      clearMarks: () => {
421	        set({ marks: [] });
422	      },
423	
424	      setChunk: (input) => {
