426	        if (seconds === null || seconds < MIN_CHUNK_SECONDS) return false;
427	        set({ chunkSeconds: seconds });
428	        return true;
429	      },
430	
431	      clearChunk: () => {
432	        set({ chunkSeconds: 0 });
433	      },
434	
435	      dismissCelebration: () => {
436	        set({ lastClaimedDino: null });
437	      },
