441	          const backend = await fetchArcProgress();
442	          if (backend?.owned_dinos) {
443	            set((state) => ({
444	              userProgress: {
445	                owned_dinos: {
446	                  ...state.userProgress.owned_dinos,
447	                  ...backend.owned_dinos,
448	                },
449	              },
450	            }));
451	          }
452	        } catch {
453	          // Ignore
454	        }
455	      },
456	    }),
