1	import { create } from 'zustand';
2	import { persist } from 'zustand/middleware';
3	import { playTick, playTimerStart, playTimerPause, playHatchFanfare, playTimerAlarm, playMarkBell } from '../core/audioFx';
4	import { isMarkHit, parseMarkInput, MAX_CUSTOM_MARKS, MIN_CHUNK_SECONDS } from '../core/timerMarks';
5	import { persistArcProgress, fetchArcProgress, resetArcProgress } from '../../../core/syncEngine';
6	import {
7	  rollWeightedDino,
8	  calculatePomodoroTime,
9	  advanceDinoOneEvo,
10	  getDinoRollChance,
11	  type PomodoroTimeResult,
12	} from '../core/dinoMath';
13	
14	export interface UserProgressData {
15	  owned_dinos: Record<string, { number: number; rank: number; ferocity?: number }>;
16	}
17	
18	export interface Clean2HSession {
19	  startedAt: number; // timestamp
20	  elapsedSeconds: number; // seconds used so far today
21	  sessionsCompletedToday: number; // number of 2H blocks completed
22	  pausedAt?: number; // timestamp when paused
23	}
24	
25	interface DinoPomodoroState {
26	  // Current Rolled Dino for Pomodoro
27	  currentDino: any | null;
28	  chancePercent: number;
29	  categoryChancePercent: number;
30	  categoryLabel: string;
31	  categoryCount: number;
32	  timeCalc: PomodoroTimeResult | null;
33	
34	  // Active Timer
35	  sessionDuration: number; // in seconds
36	  timeRemaining: number; // in seconds
37	  isRunning: boolean;
38	
39	  // Timer Marks: bell rings when elapsed time hits a mark; countdown keeps running
40	  marks: number[]; // custom checkpoints, in elapsed seconds (sorted)
41	  chunkSeconds: number; // repeating chunk size in seconds (0 = off)
42	
43	  // Audio Config
44	  soundEnabled: boolean;
45	  tickSoundEnabled: boolean;
46	
47	  // User Progress (Dinos Owned)
48	  userProgress: UserProgressData;
49	
50	  // Last Claimed Dino for Instant Celebration / Feedback
51	  lastClaimedDino: any | null;
52	
53	  // Clean 2H Pomodoro Session (10H daily limit = 5 marks × 2H each)
54	  clean2hSession: Clean2HSession | null;
55	  clean2hDailyUsedSeconds: number; // total seconds used today (max 36000 = 10H)
56	  clean2hIsRunning: boolean;
57	  endOfDayTime: number; // timestamp of 10:30 PM today
58	
59	  // Clean 2H Actions
60	  initClean2HSession: () => void;
61	  startClean2HTimer: () => void;
62	  pauseClean2HTimer: () => void;
63	  tickClean2H: () => void;
64	  syncClean2HFromBackend: () => Promise<void>;
65	
66	  // Actions
67	  initializeOrRollDino: (dinoLibrary: any[]) => void;
68	  swapDino: (dinoLibrary: any[]) => void;
69	  toggleTimer: () => void;
70	  startTimer: () => void;
71	  pauseTimer: () => void;
72	  claimDino: (dinoLibrary: any[]) => void;
73	  resetAllDinos: (dinoLibrary: any[]) => Promise<void>;
74	  tick: () => void;
75	  toggleSound: () => void;
76	  toggleTickSound: () => void;
77	  addMark: (input: string) => boolean;
78	  removeMark: (seconds: number) => void;
79	  clearMarks: () => void;
80	  setChunk: (input: string) => boolean;
81	  dismissCelebration: () => void;
82	  clearChunk: () => void;
83	  syncWithBackend: () => Promise<void>;
84	}
85	
86	export const useDinoPomodoroStore = create<DinoPomodoroState>()(
87	  persist(
88	    (set, get) => ({
89	      currentDino: null,
90	      chancePercent: 0,
91	      categoryChancePercent: 0,
92	      categoryLabel: '',
93	      categoryCount: 0,
94	      timeCalc: null,
95	
96	      sessionDuration: 25 * 60,
97	      timeRemaining: 25 * 60,
98	      isRunning: false,
99	
100	      marks: [],
101	      chunkSeconds: 0,
102	
103	      soundEnabled: true,
104	      tickSoundEnabled: false,
105	
106	      userProgress: { owned_dinos: {} },
107	      lastClaimedDino: null,
108	
109	      // Clean 2H Pomodoro - 10H daily limit (5 marks × 2H each)
110	      clean2hSession: null,
