    categoryCount,
    timeCalc,
    sessionDuration,
    timeRemaining,
    isRunning,
    soundEnabled,
    tickSoundEnabled,
    marks,
    chunkSeconds,
    userProgress,
    toggleTimer,
    swapDino,
    claimDino,
    toggleSound,
    toggleTickSound,
    // Clean 2H Pomodoro
    clean2hSession,
    clean2hDailyUsedSeconds,
    clean2hIsRunning,
    endOfDayTime,
    startClean2HTimer,
    pauseClean2HTimer,
    initClean2HSession,
    tickClean2H,
  } = useDinoPomodoroStore();

  const [timeUntilEndOfDay, setTimeUntilEndOfDay] = useState('');

  // Initialize Clean 2H session on mount
  useEffect(() => {
    initClean2HSession();

    // Update end of day countdown every second
    const updateEndOfDay = () => {
      const now = Date.now();
      const diff = endOfDayTime - now;
      if (diff <= 0) {
        setTimeUntilEndOfDay('00:00:00');
        return;
      }
      const hrs = Math.floor(diff / 3600000);
      const mins = Math.floor((diff % 3600000) / 60000);
      const secs = Math.floor((diff % 60000) / 1000);
      setTimeUntilEndOfDay(`${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`);
    };

    updateEndOfDay();
    const interval = setInterval(updateEndOfDay, 1000);
    return () => clearInterval(interval);
  }, [initClean2HSession, endOfDayTime]);

  // Clean 2H tick effect
  useEffect(() => {
    let interval: any = null;
    if (clean2hIsRunning) {
      interval = setInterval(() => {
        tickClean2H();
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
