# backend/server.py — Blue Rose Modular Storage & Integration Engine (Hot-Reload Synced)
import sys
import traceback
from pathlib import Path
from contextlib import asynccontextmanager
from fastapi import FastAPI, Request, HTTPException, WebSocket, WebSocketDisconnect
from fastapi.responses import JSONResponse
from fastapi.middleware.cors import CORSMiddleware

# Ensure backend root is in sys.path
BACKEND_ROOT = Path(__file__).resolve().parent
if str(BACKEND_ROOT) not in sys.path:
    sys.path.insert(0, str(BACKEND_ROOT))

from core.websocket_manager import ws_manager
from api.storage_router import router as storage_router
from api.curler_router import router as curler_router
from api.golden_hour_router import router as golden_hour_router
from api.heraclitus_router import router as heraclitus_router

BASE_DIR = BACKEND_ROOT / "data" / "projects"

@asynccontextmanager
async def lifespan(app: FastAPI):
    # Log cleanup on boot
    if BASE_DIR.exists():
        for proj_dir in BASE_DIR.iterdir():
            log_dir = proj_dir / "logs"
            if log_dir.exists():
                for log_file in log_dir.glob("*.log"):
                    try:
                        log_file.unlink()
                    except Exception:
                        pass

    # Preload Faust Sound Plugin if present
    try:
        SKILLS_DIR = BACKEND_ROOT.parent / ".claude" / "skills"
        if str(SKILLS_DIR) not in sys.path:
            sys.path.insert(0, str(SKILLS_DIR))
        from sound.scripts.engine import get_engine
        get_engine().preload()
        print("[VOICE] Faust Sound Plugin preloaded and warmed up successfully.")
    except Exception as e:
        print(f"[INFO] Voice synthesis plugin standby: {e}")

    print("[ROCKET] Blue Rose Modular Storage & Task Engine Online!")
    yield

app = FastAPI(title="Blue Rose Storage Engine", lifespan=lifespan)

# CORS Configuration
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Exception Handlers
@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    return JSONResponse(
        status_code=500,
        content={"detail": str(exc), "traceback": traceback.format_exc()},
        headers={"Access-Control-Allow-Origin": "*"}
    )

@app.exception_handler(HTTPException)
async def http_exception_handler(request: Request, exc: HTTPException):
    return JSONResponse(
        status_code=exc.status_code,
        content={"detail": exc.detail},
        headers={"Access-Control-Allow-Origin": "*"}
    )

# Health check endpoints
@app.get("/health")
@app.get("/api/health")
async def health_check():
    return {"status": "ok", "service": "Blue Rose Storage & Voice Engine"}

# Voice synthesis router integration
try:
    SKILLS_DIR = BACKEND_ROOT.parent / ".claude" / "skills"
    if str(SKILLS_DIR) not in sys.path:
        sys.path.insert(0, str(SKILLS_DIR))
    from sound.scripts.api import include_voice_router
    include_voice_router(app)
    print("[VOICE] Faust Voice synthesis API registered at /api/v1/voice/synthesize")
except Exception as e:
    print(f"[VOICE] Error registering voice router: {e}")

# Register Modular Routers
app.include_router(storage_router)
app.include_router(curler_router)
app.include_router(golden_hour_router)
app.include_router(heraclitus_router)

# WebSocket Endpoint for Faust Subtitles
@app.websocket("/ws/subtitle")
async def subtitle_websocket_endpoint(websocket: WebSocket):
    await ws_manager.connect(websocket)
    try:
        while True:
            await websocket.receive_text()
    except WebSocketDisconnect:
        ws_manager.disconnect(websocket)
    except Exception as e:
        print(f"[WebSocket] Error: {e}")
        ws_manager.disconnect(websocket)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(
        "server:app",
        host="0.0.0.0",
        port=8080,
        reload=True,
        reload_dirs=[str(BACKEND_ROOT)],
        reload_includes=["*.py", "*.json", ".env"],
        log_level="info"
    )

// path: src/core/api.ts

import type { ApiRequest, ApiResponse } from './types'

// NOTE: use the IPv4 literal, NOT 'localhost'. On Windows 'localhost' resolves to ::1 first; the backend only
// listens on IPv4, so every new connection stalls ~2s on the refused IPv6 attempt before falling back.
export const API_BASE = 'http://127.0.0.1:8080'
export const DEFAULT_PROJECT_ID = 'universe_25'

export interface BackendStatus {
  isOnline: boolean
  lastCheckedAt: string | null
  lastError: string | null
}

let currentStatus: BackendStatus = {
  isOnline: true,
  lastCheckedAt: null,
  lastError: null,
}

type StatusListener = (status: BackendStatus) => void
const statusListeners = new Set<StatusListener>()

export function getBackendStatus(): BackendStatus {
  return currentStatus
}

export function subscribeBackendStatus(listener: StatusListener): () => void {
  statusListeners.add(listener)
  listener(currentStatus)
  return () => {
    statusListeners.delete(listener)
  }
}

function updateStatus(isOnline: boolean, error: string | null = null) {
  currentStatus = {
    isOnline,
    lastCheckedAt: new Date().toISOString(),
    lastError: error,
  }
  statusListeners.forEach((listener) => listener(currentStatus))
}

/**
 * Health check to verify if the Blue Rose backend storage engine is running.
 */
export async function checkBackendHealth(): Promise<boolean> {
  try {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 8000)

    const res = await fetch(`${API_BASE}/health`, {
      method: 'GET',
      signal: controller.signal,
    })
    clearTimeout(timeoutId)

    if (res.ok) {
      updateStatus(true, null)
      return true
    } else {
      const errText = `Backend returned HTTP status ${res.status}`
      updateStatus(false, errText)
      return false
    }
  } catch (err) {
    const errText = err instanceof Error ? err.message : 'Backend connection failed'
    updateStatus(false, errText)
    return false
  }
}

/**
 * Single reusable function for all backend communication.
 * Every call goes through POST /api/v1/execute.
 * Never silently swallows errors!
 */
async function executeRaw<T = unknown>(
  tier: string,
  action: string,
  key?: string,
  data?: unknown,
  projectId: string = DEFAULT_PROJECT_ID
): Promise<ApiResponse<T>> {
  const body: ApiRequest = {
    project_id: projectId,
    tier,
    order: { action, ...(key && { key }), ...(data !== undefined && { data }) },
  }

  try {
    const res = await fetch(`${API_BASE}/api/v1/execute`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })

    if (!res.ok) {
      const err = await res.json().catch(() => ({ detail: res.statusText }))
      const errorMsg = err.detail || `API error HTTP ${res.status}`
      updateStatus(false, errorMsg)
      throw new Error(`[Backend Engine Error] ${errorMsg}`)
    }

    const json = await res.json()
    updateStatus(true, null)
    return json
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Network failure contacting backend'
    updateStatus(false, errorMsg)
    throw new Error(`[Backend Unreachable] ${errorMsg}`)
  }
}

// =============================================================================
// [REQUEST ACTIVITY TRACKER] - lets UIs explain *what* they are waiting for
// =============================================================================
export interface ApiActivityEntry {
  label: string
  startedAt: number
}

export interface ApiActivity {
  inFlight: ApiActivityEntry[]
  lastLabel: string | null
  lastMs: number | null
}

let activitySeq = 0
const activeRequests = new Map<number, ApiActivityEntry>()
let activitySnapshot: ApiActivity = { inFlight: [], lastLabel: null, lastMs: null }
const activityListeners = new Set<(a: ApiActivity) => void>()

function publishActivity(lastLabel?: string, lastMs?: number) {
  activitySnapshot = {
    inFlight: Array.from(activeRequests.values()),
    lastLabel: lastLabel ?? activitySnapshot.lastLabel,
    lastMs: lastMs ?? activitySnapshot.lastMs,
  }
  activityListeners.forEach((l) => l(activitySnapshot))
}

export function getApiActivity(): ApiActivity {
  return activitySnapshot
}

export function subscribeApiActivity(listener: (a: ApiActivity) => void): () => void {
  activityListeners.add(listener)
  return () => {
    activityListeners.delete(listener)
  }
}

/**
 * Single reusable function for all backend communication (tracked wrapper around executeRaw).
 */
export async function execute<T = unknown>(
  tier: string,
  action: string,
  key?: string,
  data?: unknown,
  projectId: string = DEFAULT_PROJECT_ID
): Promise<ApiResponse<T>> {
  const id = ++activitySeq
  const label = `T${tier}:${action}`
  const startedAt = performance.now()
  activeRequests.set(id, { label, startedAt })
  publishActivity()
  try {
    return await executeRaw<T>(tier, action, key, data, projectId)
  } finally {
    activeRequests.delete(id)
    publishActivity(label, Math.round(performance.now() - startedAt))
  }
}

