import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { playTick, playTimerStart, playTimerPause, playHatchFanfare, playTimerAlarm, playMarkBell } from '../core/audioFx';
import { isMarkHit, parseMarkInput, MAX_CUSTOM_MARKS, MIN_CHUNK_SECONDS } from '../core/timerMarks';
import { persistArcProgress, fetchArcProgress, resetArcProgress } from '../../../core/syncEngine';
import {
  rollWeightedDino,
  calculatePomodoroTime,
  advanceDinoOneEvo,
  getDinoRollChance,
  type PomodoroTimeResult,
} from '../core/dinoMath';

export interface UserProgressData {
  owned_dinos: Record<string, { number: number; rank: number; ferocity?: number }>;
}

export interface Clean2HSession {
  startedAt: number; // timestamp
  elapsedSeconds: number; // seconds used so far today
  sessionsCompletedToday: number; // number of 2H blocks completed
  pausedAt?: number; // timestamp when paused
}

interface DinoPomodoroState {
  // Current Rolled Dino for Pomodoro
  currentDino: any | null;
  chancePercent: number;
  categoryChancePercent: number;
  categoryLabel: string;
  categoryCount: number;
  timeCalc: PomodoroTimeResult | null;

  // Active Timer
  sessionDuration: number; // in seconds
  timeRemaining: number; // in seconds
  isRunning: boolean;

  // Timer Marks: bell rings when elapsed time hits a mark; countdown keeps running
  marks: number[]; // custom checkpoints, in elapsed seconds (sorted)
  chunkSeconds: number; // repeating chunk size in seconds (0 = off)

  // Audio Config
  soundEnabled: boolean;
  tickSoundEnabled: boolean;

  // User Progress (Dinos Owned)
  userProgress: UserProgressData;

  // Last Claimed Dino for Instant Celebration / Feedback
  lastClaimedDino: any | null;

  // Clean 2H Pomodoro Session (10H daily limit = 5 marks × 2H each)
  clean2hSession: Clean2HSession | null;
  clean2hDailyUsedSeconds: number; // total seconds used today (max 36000 = 10H)
  clean2hIsRunning: boolean;
  endOfDayTime: number; // timestamp of 10:30 PM today

  // Clean 2H Actions
  initClean2HSession: () => void;
  startClean2HTimer: () => void;
  pauseClean2HTimer: () => void;
  tickClean2H: () => void;
  syncClean2HFromBackend: () => Promise<void>;

  // Actions
  initializeOrRollDino: (dinoLibrary: any[]) => void;
  swapDino: (dinoLibrary: any[]) => void;
  toggleTimer: () => void;
  startTimer: () => void;
  pauseTimer: () => void;
  claimDino: (dinoLibrary: any[]) => void;
  resetAllDinos: (dinoLibrary: any[]) => Promise<void>;
  tick: () => void;
  toggleSound: () => void;
  toggleTickSound: () => void;
  addMark: (input: string) => boolean;
  removeMark: (seconds: number) => void;
  clearMarks: () => void;
  setChunk: (input: string) => boolean;
  dismissCelebration: () => void;
  clearChunk: () => void;
  syncWithBackend: () => Promise<void>;
}

export const useDinoPomodoroStore = create<DinoPomodoroState>()(
  persist(
    (set, get) => ({
      currentDino: null,
      chancePercent: 0,
      categoryChancePercent: 0,
      categoryLabel: '',
      categoryCount: 0,
      timeCalc: null,

      sessionDuration: 25 * 60,
      timeRemaining: 25 * 60,
      isRunning: false,

      marks: [],
      chunkSeconds: 0,

      soundEnabled: true,
      tickSoundEnabled: false,

      userProgress: { owned_dinos: {} },
      lastClaimedDino: null,

      // Clean 2H Pomodoro - 10H daily limit (5 marks × 2H each)
      clean2hSession: null,
      clean2hDailyUsedSeconds: 0,
      clean2hIsRunning: false,
      endOfDayTime: (() => {
        const now = new Date();
        const end = new Date(now);
        end.setHours(22, 30, 0, 0);
        if (end < now) end.setDate(end.getDate() + 1);
        return end.getTime();
      })(),

      initClean2HSession: () => {
        const now = Date.now();
        set({
          clean2hSession: {
            startedAt: now,
            elapsedSeconds: 0,
            sessionsCompletedToday: 0,
          },
          clean2hIsRunning: false,
        });
      },

      startClean2HTimer: () => {
        const { clean2hSession, clean2hDailyUsedSeconds } = get();
        if (!clean2hSession) {
          get().initClean2HSession();
        }
        // Check if daily limit (10H = 36000 seconds) reached
        if (clean2hDailyUsedSeconds >= 36000) return;

        set({ clean2hIsRunning: true });
      },

      pauseClean2HTimer: () => {
        set((state) => ({
          clean2hIsRunning: false,
          clean2hSession: state.clean2hSession
            ? { ...state.clean2hSession, pausedAt: Date.now() }
            : null,
        }));
      },

      tickClean2H: () => {
        const { clean2hSession, clean2hIsRunning, clean2hDailyUsedSeconds } = get();
        if (!clean2hIsRunning || !clean2hSession) return;

        const newElapsed = clean2hSession.elapsedSeconds + 1;
        const newUsed = clean2hDailyUsedSeconds + 1;

        // Check if a 2H block (7200 seconds) is completed
        const sessionsNow = Math.floor(newUsed / 7200);

        // Check if daily limit (10H) reached
        if (newUsed >= 36000) {
          set({
