                    """, where_params)
                    channels = [{"name": r[0], "channel_id": r[1] or "", "count": r[2], "avg_hazard": 3.0, "best_id": "", "best_thumbnail": "", "best_title": ""} for r in cursor.fetchall()]
                return {"data": {"channels": channels}}

            elif act == "purge_channel":
                if target_table not in tables:
