export const useDinoPomodoroStore = create<DinoPomodoroState>()(
  persist(
    (set, get) => ({
      currentDino: null,
      chancePercent: 0,
      categoryChancePercent: 0,
      categoryLabel: '',
      categoryCount: 0,
      timeCalc: null,

      sessionDuration: 25 * 60,
      timeRemaining: 25 * 60,
      isRunning: false,

      marks: [],
      chunkSeconds: 0,

      soundEnabled: true,
      tickSoundEnabled: false,

      userProgress: { owned_dinos: {} },
      lastClaimedDino: null,

      // Clean 2H Pomodoro - 10H daily limit (5 marks × 2H each)
      clean2hSession: null,
      clean2hDailyUsedSeconds: 0,
      clean2hIsRunning: false,
      endOfDayTime: (() => {
        const now = new Date();
        const end = new Date(now);
        end.setHours(22, 30, 0, 0);
        if (end < now) end.setDate(end.getDate() + 1);
        return end.getTime();
      })(),

      initClean2HSession: () => {
        const now = Date.now();
        set({
          clean2hSession: {
            startedAt: now,
            elapsedSeconds: 0,
            sessionsCompletedToday: 0,
          },
          clean2hIsRunning: false,
        });
      },

      startClean2HTimer: () => {
        const { clean2hSession, clean2hDailyUsedSeconds } = get();
        if (!clean2hSession) {
          get().initClean2HSession();
        }
        // Check if daily limit (10H = 36000 seconds) reached
        if (clean2hDailyUsedSeconds >= 36000) return;

        set({ clean2hIsRunning: true });
      },

      pauseClean2HTimer: () => {
        set((state) => ({
          clean2hIsRunning: false,
          clean2hSession: state.clean2hSession
            ? { ...state.clean2hSession, pausedAt: Date.now() }
            : null,
        }));
      },

      tickClean2H: () => {
        const { clean2hSession, clean2hIsRunning, clean2hDailyUsedSeconds } = get();
        if (!clean2hIsRunning || !clean2hSession) return;

        const newElapsed = clean2hSession.elapsedSeconds + 1;
        const newUsed = clean2hDailyUsedSeconds + 1;

        // Check if a 2H block (7200 seconds) is completed
        const sessionsNow = Math.floor(newUsed / 7200);

        // Check if daily limit (10H) reached
        if (newUsed >= 36000) {
          set({
            clean2hIsRunning: false,
            clean2hSession: {
              ...clean2hSession,
              elapsedSeconds: newElapsed,
              sessionsCompletedToday: sessionsNow,
            },
            clean2hDailyUsedSeconds: 36000,
          });
          return;
        }

        set({
          clean2hSession: {
            ...clean2hSession,
            elapsedSeconds: newElapsed,
            sessionsCompletedToday: sessionsNow,
          },
          clean2hDailyUsedSeconds: newUsed,
        });
      },

      syncClean2HFromBackend: async () => {
        // TODO: Fetch from backend
        // const res = await execute('clean_2h_pomodoro', 'read_all');
      },

      initializeOrRollDino: (dinoLibrary) => {
        if (!dinoLibrary || dinoLibrary.length === 0) return;
        const { currentDino, userProgress } = get();

        // If a dino is already rolled, recompute its time calculation and pool chance with current userProgress
        if (currentDino) {
          const uuid = currentDino.uuid || currentDino.id || currentDino.name;
          const userCount = Number(userProgress.owned_dinos[uuid]?.number || 0);
          const calc = calculatePomodoroTime(currentDino, userCount, userProgress);
          const rollData = getDinoRollChance(currentDino, dinoLibrary, userProgress);
          const prev = get();

