213	export async function hydrateAllStores(): Promise<{ success: boolean }> {
214	  const [invRes, vaultRes, farmsRes] = await Promise.all([
215	    execute<BackendInventoryData>('inventory', 'read_all'),
216	    execute<BackendVaultData>('vault', 'read_all'),
217	    execute<BackendFarmsData>('farms', 'read_all'),
218	  ])
219	
220	  const invData = invRes.data || {}
221	  const vaultData = vaultRes.data || {}
222	  const farmsData = farmsRes.data || {}
223	
224	  // Time balance is now stored in the inventory table as 'time' currency row
225	  const extractInvAmount = (item: any): number => {
226	    if (typeof item === 'number') return item
227	    if (item && typeof item === 'object' && 'amount' in item) return Number(item.amount || 0)
228	    return 0
229	  }
230	
231	  // Time balance is stored in inventory table as 'time' currency row
232	  const timeBalance = extractInvAmount(invData.time) || 3600
233	  useCurrencyStore.setState({ timeBalance })
234	
235	  useInventoryStore.setState({
