  try {
    const res = await execute<Record<string, PomodoroBackendState>>('dino_pomodoro', 'read_all')
    const rows = res.data || {}
    return rows.daily_state || Object.values(rows)[0] || null
  } catch (err) {
    console.warn('[SyncEngine] Fetching pomodoro timer state failed:', err)
    return null
