  persist(
    (set, get) => ({
      currentDino: null,
      chancePercent: 0,
      categoryChancePercent: 0,
      categoryLabel: '',
      categoryCount: 0,
      timeCalc: null,

      sessionDuration: POMODORO_2H_SECONDS,
      timeRemaining: POMODORO_2H_SECONDS,
      isRunning: false,

      focusDayKey: getLocalDateKey(),
      focusTotalUsedSeconds: 0,
      focusCompletedPomodoros: 0,

      marks: [],
