200	 * - Weight = (1 + 0.1 * partnerCount) / Next_Evo_Ferocity
201	 * - Chance = Weight / sum(Weights)
202	 * Also aggregates total weights and specimen counts per category (rarity + hybrid_type).
203	 */
204	export function calculateDinoPoolWeights(
205	  dinoLibrary: any[],
206	  userProgress?: any,
207	  cachedRelationsMap?: Map<string, Set<string>>
208	): {
209	  weights: Map<string, number>;
210	  metaMap: Map<string, { nextEvoFerocity: number; partnerCount: number; bonusMultiplier: number; modifiedFerocity: number }>;
211	  categoryWeights: Map<string, number>;
212	  categoryCounts: Map<string, number>;
213	  totalPoolFerocity: number;
214	  relationsMap: Map<string, Set<string>>;
215	} {
216	  const relationsMap = cachedRelationsMap || getDinoRelationsMap(dinoLibrary);
217	  const weights = new Map<string, number>();
218	  const metaMap = new Map<string, { nextEvoFerocity: number; partnerCount: number; bonusMultiplier: number; modifiedFerocity: number }>();
219	  const categoryWeights = new Map<string, number>();
220	  const categoryCounts = new Map<string, number>();
221	  let totalPoolWeight = 0;
222	
223	  for (const dino of dinoLibrary) {
224	    const uuid = dino.uuid || dino.id || dino.name;
225	    const calc = getDinoModifiedFerocity(dino, userProgress, relationsMap);
226	
227	    // Inverse weighting: higher ferocity = lower chance; partner affinity boosts roll weight
228	    const weight = calc.nextEvoFerocity > 0 ? calc.bonusMultiplier / calc.nextEvoFerocity : 0.001;
229	
230	    weights.set(uuid, weight);
231	    metaMap.set(uuid, calc);
232	    totalPoolWeight += weight;
233	
234	    const catKey = getDinoCategoryKey(dino);
235	    categoryWeights.set(catKey, (categoryWeights.get(catKey) || 0) + weight);
236	    categoryCounts.set(catKey, (categoryCounts.get(catKey) || 0) + 1);
237	  }
238	
239	  return {
240	    weights,
241	    metaMap,
242	    categoryWeights,
243	    categoryCounts,
244	    totalPoolFerocity: totalPoolWeight,
245	    relationsMap,
246	  };
