  {dailyMarks.map((m) => {
    return (
      <div
        key={m.index}
        title={`Mark ${m.index + 1}: 2H block (${m.isCompleted ? 'Completed' : m.isActive ? `${formatHMS(m.remainingSeconds)} remaining` : 'Upcoming'})`}
        className={`relative rounded-2xl p-2.5 sm:p-3 flex flex-col items-center justify-center text-center transition-all duration-300 select-none ${
          m.isCompleted
            ? 'bg-gradient-to-b from-[#0b2416] to-[#08170e] border border-emerald-400/50 shadow-[0_0_15px_rgba(16,185,129,0.2)]'
            : m.isActive
            ? 'bg-gradient-to-b from-[#241a0d] to-[#140e1f] border-2 border-amber-400 shadow-[0_0_20px_rgba(251,191,36,0.3)] scale-[1.03] z-10'
            : 'bg-[#120d1c]/80 border border-[#2b213b] opacity-60'
        }`}
      >
        {/* SVG Radial Arc for each 2H Mark */}
        <div className="relative w-11 h-11 sm:w-13 sm:h-13 my-1 flex items-center justify-center">
          <svg className="w-full h-full -rotate-90 overflow-visible" viewBox="0 0 48 48">
            <circle
              cx="24"
              cy="24"
              r="20"
              fill="none"
              stroke="rgba(255, 255, 255, 0.08)"
              strokeWidth="3.5"
            />
            <circle
              cx="24"
              cy="24"
              r="20"
              fill="none"
              stroke={m.isCompleted ? '#10b981' : m.isActive ? '#f59e0b' : 'transparent'}
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeDasharray="125.66"
              strokeDashoffset={125.66 * (1 - m.progressPercent / 100)}
              className="transition-all duration-500 ease-linear"
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            {m.isCompleted ? (
              <CheckCircle2 className="w-5 h-5 text-emerald-400" />
            ) : (
              <span
                className={`font-mono text-[11px] font-bold ${
                  m.isActive ? 'text-amber-300' : 'text-zinc-500'
                }`}
              >
                {m.isActive ? `${Math.round(m.progressPercent)}%` : m.index + 1}
              </span>
            )}
          </div>
        </div>

        {/* Mark Label & 2H Value */}
        <span className="font-cinzel text-[10px] sm:text-xs font-bold text-white uppercase mt-1">
          Mark {m.index + 1}
        </span>
        <span className="text-[9.5px] font-mono text-amber-300/80 font-bold">
          {m.label}
        </span>
      </div>
    );
  })}
</div>

